input.new_string:
import { describe, expect, test } from "bun:test";
import { greet, add, greetWithPrefix } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  describe("greetWithPrefix", () => {
    test("returns greeting with custom prefix and name", () => {
      expect(greetWithPrefix("Good morning", "Alice")).toBe(
        "Good morning, Alice!"
      );
    });

    test("returns greeting with different prefix", () => {
      expect(greetWithPrefix("Welcome", "Bob")).toBe("Welcome, Bob!");
    });

    test("falls back to default greeting when prefix is empty", () => {
      expect(greetWithPrefix("", "Alice")).toBe("Hello, Alice!");
    });

    test("returns prefix only when name is empty", () => {
      expect(greetWithPrefix("Good morning", "")).toBe("Good morning!");
    });

    test("returns generic greeting when both prefix and name are empty", () => {
      expect(greetWithPrefix("", "")).toBe("Hello!");
    });

    test("trims whitespace from prefix and name", () => {
      expect(greetWithPrefix("  Welcome  ", "  Alice  ")).toBe(
        "Welcome, Alice!"
      );
    });
  });
});

