/**
 * Greet someone by name with a custom prefix.
 * @param prefix - The greeting prefix (e.g., "Good morning", "Welcome")
 * @param name - The name of the person to greet
 * @returns A greeting string combining the prefix and name
 */
export function greetWithPrefix(prefix: string, name: string): string {
  const trimmedPrefix = prefix.trim();
  const trimmedName = name.trim();

  if (!trimmedPrefix && !trimmedName) {
    return "Hello!";
  }

  if (!trimmedPrefix) {
    return `Hello, ${trimmedName}!`;
  }

  if (!trimmedName) {
    return `${trimmedPrefix}!`;
  }

  return `${trimmedPrefix}, ${trimmedName}!`;
}
