/**
 * High-performance JSON validation using character-level scanning.
 * Avoids exception-based flow control (no JSON.parse try-catch).
 */

/** Result of a JSON validation check. */
export interface ValidationResult {
  valid: boolean;
  errorPosition: number | null;
  errorMessage: string | null;
}

const WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0d]); // space, tab, LF, CR

function success(): ValidationResult {
  return { valid: true, errorPosition: null, errorMessage: null };
}

function failure(position: number, message: string): ValidationResult {
  return { valid: false, errorPosition: position, errorMessage: message };
}

/**
 * Validate a JSON string using character-level scanning.
 * Returns a ValidationResult indicating whether the input is valid JSON,
 * and if not, the position and description of the first error.
 */
export function validateJson(input: string): ValidationResult {
  if (input.length === 0) {
    return failure(0, "Unexpected end of input");
  }

  let pos = 0;
  const len = input.length;

  function skipWhitespace(): void {
    while (pos < len && WHITESPACE.has(input.charCodeAt(pos))) {
      pos++;
    }
  }

  function parseValue(): ValidationResult {
    skipWhitespace();
    if (pos >= len) {
      return failure(pos, "Unexpected end of input");
    }

    const ch = input.charCodeAt(pos);

    if (ch === 0x22) return parseString(); // "
    if (ch === 0x7b) return parseObject(); // {
    if (ch === 0x5b) return parseArray();  // [
    if (ch === 0x74) return parseLiteral("true");
    if (ch === 0x66) return parseLiteral("false");
    if (ch === 0x6e) return parseLiteral("null");
    if (ch === 0x2d || (ch >= 0x30 && ch <= 0x39)) return parseNumber(); // - or 0-9

    return failure(pos, `Unexpected character '${input[pos]}'`);
  }

  function parseLiteral(expected: string): ValidationResult {
    for (let i = 0; i < expected.length; i++) {
      if (pos >= len) {
        return failure(pos, `Unexpected end of input while parsing '${expected}'`);
      }
      if (input[pos] !== expected[i]) {
        return failure(pos, `Expected '${expected}', got '${input.slice(pos, pos + expected.length)}'`);
      }
      pos++;
    }
    return success();
  }

  function parseString(): ValidationResult {
    if (input.charCodeAt(pos) !== 0x22) {
      return failure(pos, "Expected '\"'");
    }
    pos++; // skip opening quote

    while (pos < len) {
      const ch = input.charCodeAt(pos);

      if (ch === 0x22) { // closing quote
        pos++;
        return success();
      }

      if (ch === 0x5c) { // backslash
        pos++;
        if (pos >= len) {
          return failure(pos, "Unexpected end of input in string escape");
        }
        const esc = input.charCodeAt(pos);
        if (
          esc === 0x22 || // "
          esc === 0x5c || // \
          esc === 0x2f || // /
          esc === 0x62 || // b
          esc === 0x66 || // f
          esc === 0x6e || // n
          esc === 0x72 || // r
          esc === 0x74    // t
        ) {
          pos++;
          continue;
        }
        if (esc === 0x75) { // u
          pos++;
          for (let i = 0; i < 4; i++) {
            if (pos >= len) {
              return failure(pos, "Unexpected end of input in unicode escape");
            }
            const hex = input.charCodeAt(pos);
            if (
              !(hex >= 0x30 && hex <= 0x39) && // 0-9
              !(hex >= 0x41 && hex <= 0x46) && // A-F
              !(hex >= 0x61 && hex <= 0x66)    // a-f
            ) {
              return failure(pos, `Invalid unicode escape character '${input[pos]}'`);
            }
            pos++;
          }
          continue;
        }
        return failure(pos, `Invalid escape character '${input[pos]}'`);
      }

      // Control characters (U+0000 through U+001F) are not allowed unescaped
      if (ch < 0x20) {
        return failure(pos, "Unescaped control character in string");
      }

      pos++;
    }

    return failure(pos, "Unterminated string");
  }

  function parseNumber(): ValidationResult {
    const start = pos;

    // Optional minus
    if (pos < len && input.charCodeAt(pos) === 0x2d) {
      pos++;
    }

    // Integer part
    if (pos >= len) {
      return failure(pos, "Unexpected end of input in number");
    }

    if (input.charCodeAt(pos) === 0x30) { // leading zero
      pos++;
      // After a leading zero, next must not be a digit
      if (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        return failure(pos, "Leading zeros are not allowed");
      }
    } else if (input.charCodeAt(pos) >= 0x31 && input.charCodeAt(pos) <= 0x39) {
      pos++;
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    } else {
      return failure(pos, `Invalid number character '${input[pos]}'`);
    }

    // Fraction
    if (pos < len && input.charCodeAt(pos) === 0x2e) { // .
      pos++;
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return failure(pos, "Expected digit after decimal point");
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    // Exponent
    if (pos < len && (input.charCodeAt(pos) === 0x65 || input.charCodeAt(pos) === 0x45)) { // e or E
      pos++;
      if (pos < len && (input.charCodeAt(pos) === 0x2b || input.charCodeAt(pos) === 0x2d)) { // + or -
        pos++;
      }
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return failure(pos, "Expected digit in exponent");
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    if (pos === start) {
      return failure(pos, "Invalid number");
    }

    return success();
  }

  function parseObject(): ValidationResult {
    pos++; // skip {
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x7d) { // }
      pos++;
      return success();
    }

    while (true) {
      skipWhitespace();
      if (pos >= len) {
        return failure(pos, "Unexpected end of input in object");
      }

      // Key must be a string
      if (input.charCodeAt(pos) !== 0x22) {
        return failure(pos, "Expected string key in object");
      }
      const keyResult = parseString();
      if (!keyResult.valid) return keyResult;

      skipWhitespace();
      if (pos >= len || input.charCodeAt(pos) !== 0x3a) { // :
        return failure(pos, "Expected ':' after object key");
      }
      pos++;

      const valueResult = parseValue();
      if (!valueResult.valid) return valueResult;

      skipWhitespace();
      if (pos >= len) {
        return failure(pos, "Unexpected end of input in object");
      }

      if (input.charCodeAt(pos) === 0x7d) { // }
        pos++;
        return success();
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return failure(pos, "Expected ',' or '}' in object");
      }
      pos++;
    }
  }

  function parseArray(): ValidationResult {
    pos++; // skip [
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x5d) { // ]
      pos++;
      return success();
    }

    while (true) {
      const valueResult = parseValue();
      if (!valueResult.valid) return valueResult;

      skipWhitespace();
      if (pos >= len) {
        return failure(pos, "Unexpected end of input in array");
      }

      if (input.charCodeAt(pos) === 0x5d) { // ]
        pos++;
        return success();
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return failure(pos, "Expected ',' or ']' in array");
      }
      pos++;
    }
  }

  const result = parseValue();
  if (!result.valid) return result;

  skipWhitespace();
  if (pos < len) {
    return failure(pos, "Unexpected content after valid JSON");
  }

  return success();
}

// CLI entry point
if (import.meta.main) {
  async function main(): Promise<void> {
    const args = process.argv.slice(2);

    if (args.length > 0) {
      for (const filePath of args) {
        try {
          const content = await Bun.file(filePath).text();
          const result = validateJson(content);
          if (result.valid) {
            console.log(`${filePath}: valid`);
          } else {
            console.error(`${filePath}: invalid at position ${result.errorPosition} - ${result.errorMessage}`);
            process.exitCode = 1;
          }
        } catch (err) {
          console.error(`${filePath}: ${(err as Error).message}`);
          process.exitCode = 1;
        }
      }
    } else {
      const chunks: Buffer[] = [];
      for await (const chunk of Bun.stdin.stream()) {
        chunks.push(Buffer.from(chunk));
      }
      const content = Buffer.concat(chunks).toString("utf-8");
      const result = validateJson(content);
      if (result.valid) {
        console.log("stdin: valid");
      } else {
        console.error(`stdin: invalid at position ${result.errorPosition} - ${result.errorMessage}`);
        process.exitCode = 1;
      }
    }
  }

  main();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";
import type { ValidationResult } from "./validate-json";

describe("validateJson", () => {
  describe("valid JSON", () => {
    test("parses empty object", () => {
      const result = validateJson("{}");
      expect(result.valid).toBe(true);
      expect(result.errorPosition).toBeNull();
      expect(result.errorMessage).toBeNull();
    });

    test("parses empty array", () => {
      expect(validateJson("[]").valid).toBe(true);
    });

    test("parses string value", () => {
      expect(validateJson('"hello"').valid).toBe(true);
    });

    test("parses number values", () => {
      expect(validateJson("42").valid).toBe(true);
      expect(validateJson("-1").valid).toBe(true);
      expect(validateJson("3.14").valid).toBe(true);
      expect(validateJson("1e10").valid).toBe(true);
      expect(validateJson("2.5E-3").valid).toBe(true);
      expect(validateJson("0").valid).toBe(true);
    });

    test("parses boolean and null literals", () => {
      expect(validateJson("true").valid).toBe(true);
      expect(validateJson("false").valid).toBe(true);
      expect(validateJson("null").valid).toBe(true);
    });

    test("parses object with key-value pairs", () => {
      expect(validateJson('{"name": "Alice", "age": 30}').valid).toBe(true);
    });

    test("parses nested objects and arrays", () => {
      const input = '{"a": {"b": [1, 2, {"c": true}]}, "d": null}';
      expect(validateJson(input).valid).toBe(true);
    });

    test("parses string with escape sequences", () => {
      expect(validateJson('"hello\\nworld"').valid).toBe(true);
      expect(validateJson('"tab\\there"').valid).toBe(true);
      expect(validateJson('"quote\\"inside"').valid).toBe(true);
      expect(validateJson('"backslash\\\\"').valid).toBe(true);
      expect(validateJson('"slash\\/"').valid).toBe(true);
    });

    test("parses string with unicode escapes", () => {
      expect(validateJson('"\\u0041"').valid).toBe(true);
      expect(validateJson('"\\u00e9"').valid).toBe(true);
      expect(validateJson('"\\uFFFF"').valid).toBe(true);
    });

    test("parses JSON with whitespace", () => {
      expect(validateJson("  { } ").valid).toBe(true);
      expect(validateJson("\n[\n  1,\n  2\n]\n").valid).toBe(true);
      expect(validateJson("\t{\t\"a\"\t:\t1\t}").valid).toBe(true);
    });
  });

  describe("invalid JSON", () => {
    test("rejects empty input", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.errorPosition).toBe(0);
      expect(result.errorMessage).toBe("Unexpected end of input");
    });

    test("rejects missing closing bracket", () => {
      const result = validateJson("[1, 2");
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Unexpected end of input");
    });

    test("rejects missing closing brace", () => {
      const result = validateJson('{"a": 1');
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Unexpected end of input");
    });

    test("rejects trailing comma in array", () => {
      const result = validateJson("[1, 2,]");
      expect(result.valid).toBe(false);
    });

    test("rejects trailing comma in object", () => {
      const result = validateJson('{"a": 1,}');
      expect(result.valid).toBe(false);
    });

    test("rejects unquoted object keys", () => {
      const result = validateJson("{a: 1}");
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Expected string key");
    });

    test("rejects single quotes", () => {
      const result = validateJson("'hello'");
      expect(result.valid).toBe(false);
    });

    test("rejects leading zeros in numbers", () => {
      const result = validateJson("01");
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Leading zeros");
    });

    test("rejects invalid unicode escape", () => {
      const result = validateJson('"\\uGGGG"');
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("unicode escape");
    });

    test("rejects truncated unicode escape", () => {
      const result = validateJson('"\\u00"');
      expect(result.valid).toBe(false);
    });

    test("rejects unterminated string", () => {
      const result = validateJson('"hello');
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Unterminated string");
    });

    test("rejects invalid escape sequence", () => {
      const result = validateJson('"\\x41"');
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Invalid escape");
    });

    test("rejects content after valid JSON", () => {
      const result = validateJson("true false");
      expect(result.valid).toBe(false);
      expect(result.errorMessage).toContain("Unexpected content");
    });

    test("reports error position accurately", () => {
      const result = validateJson('{"valid": true, bad}');
      expect(result.valid).toBe(false);
      expect(result.errorPosition).toBe(16);
    });
  });

  describe("edge cases", () => {
    test("handles deeply nested structures", () => {
      const depth = 100;
      const input = "[".repeat(depth) + "1" + "]".repeat(depth);
      expect(validateJson(input).valid).toBe(true);
    });

    test("handles deeply nested objects", () => {
      const depth = 50;
      let input = "";
      for (let i = 0; i < depth; i++) {
        input += '{"a":';
      }
      input += "1";
      for (let i = 0; i < depth; i++) {
        input += "}";
      }
      expect(validateJson(input).valid).toBe(true);
    });

    test("handles string with multibyte unicode characters", () => {
      expect(validateJson('"cafe\\u0301"').valid).toBe(true);
    });

    test("handles large array payload", () => {
      const items = Array.from({ length: 10000 }, (_, i) => i).join(",");
      const input = `[${items}]`;
      expect(validateJson(input).valid).toBe(true);
    });

    test("handles negative zero", () => {
      expect(validateJson("-0").valid).toBe(true);
    });

    test("handles exponent-only number", () => {
      expect(validateJson("1E2").valid).toBe(true);
    });

    test("rejects bare minus sign", () => {
      const result = validateJson("-");
      expect(result.valid).toBe(false);
    });

    test("rejects number with trailing dot", () => {
      const result = validateJson("1.");
      expect(result.valid).toBe(false);
    });
  });
});

